using System;using System.IO;using System.IO.Compression;using System.Collections.Generic;using System.Drawing;using System.Drawing.Imaging;using System.Reflection;using System.Windows.Forms;using EanEtikety;
class Revision310Tests {
 static int count;static string dir;static void Check(bool ok,string message){count++;if(!ok)throw new Exception(message);}static void Reject(Action action,string message){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,message);}
 static readonly BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,flags).Invoke(o,args);}static T Field<T>(object o,string n){return (T)o.GetType().GetField(n,flags).GetValue(o);}
 [STAThread]static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  var old=ProjectXml.Decode<LabelSettings>("<LabelSettings><Width>60</Width><Height>45</Height></LabelSettings>");Check(old.Layout!=null&&old.Variables.Count==0&&!old.HideBarcode,"old projects default new fields");
  var s=LabelSettings.Default();var history=new EditHistory();history.Reset(s);s.Texts[0].Text="Changed";history.Record(s);Check(history.Undo().Texts[0].Text!="Changed","undo content");Check(history.Redo().Texts[0].Text=="Changed","redo content");history.Undo();s.Width=70;history.Record(s);Check(!history.CanRedo,"new branch discards redo");
  string project=Path.Combine(dir,"unicode.ean.xml");s.Texts[0].Text="Žltý čaj – árvíztűrő";ProjectXml.Save(project,s);Check(Engine.Load(project).Texts[0].Text==s.Texts[0].Text,"atomic UTF8 XML roundtrip");
  string preferences=Path.Combine(dir,"recovery-prefs");using(var store=new WorkspaceStore(preferences)){store.SaveRecovery(s,null);using(var live=new WorkspaceStore(preferences)){int found=0;live.Recoverable((p,d)=>found++,e=>{throw new Exception(e);});Check(found==0,"active recovery protected by lease");}}using(var store=new WorkspaceStore(preferences)){int found=0;store.Recoverable((p,d)=>{found++;Check(d.OriginalPath==null&&d.Label.Texts[0].Text==s.Texts[0].Text,"unnamed recovery content");File.Delete(p);},e=>{throw new Exception(e);});Check(found==1,"crash recovery discovered");}
  var csv=BatchData.CsvText("EAN;Name;Qty\r\n00123;\"Čaj; zelený\";2\r\n00045;\"two\r\nlines\";1",';');Check(csv.Rows.Count==3&&csv.Rows[1][0]=="00123"&&csv.Rows[2][1].Contains("\r\n"),"CSV zeros delimiters multiline unicode");Reject(()=>BatchData.CsvText("\"open",';'),"malformed CSV rejected");
  s=LabelSettings.Default();s.Kind=128;s.Ean="{serial}";s.Variables.Add(new VariableField{Name="serial",Start=7,Step=2,Digits=5});s.Variables.Add(new VariableField{Name="date",Type="Date",Days=3});s.Texts[0].Text="{date}";var instant=new DateTime(2026,10,7);var record=BatchData.Record(s,new string[0],new List<ColumnBinding>(),-1,1,2,instant);Check(record.Error==null&&record.Label.Ean=="00009"&&record.Label.Texts[0].Text=="2026-10-10","frozen variables");Check(BatchData.Record(s,new string[0],new List<ColumnBinding>(),-1,1,2,instant).Label.Ean==record.Label.Ean,"preview does not advance sequence");
  var invalid=BatchData.Record(s,new[]{"0"},new List<ColumnBinding>(),0,0,1,instant);Check(invalid.Error!=null,"invalid quantity explicit");Reject(()=>OutputPlan.Create(new List<BatchRecord>{invalid},s),"bad row blocks output");
  s=LabelSettings.Default();s.UsePaper=true;s.PageWidth=210;s.PageHeight=297;s.Layout=new SheetLayout{Enabled=true,Columns=3,Rows=5,FirstSlot=14,Count=3};var plan=OutputPlan.Create(s);Check(plan.PageCount==2&&plan.Placements.Count==3,"first unused slot multipage");Check(Math.Abs(plan.Placements[0].Bounds.X-134)<.001&&plan.Placements[1].Bounds.X==10,"sheet positions");using(var doc=new LabelPrintDocument(s,plan)){Check(doc.PageCount==plan.PageCount&&doc.LabelBounds(0)==plan.Placements[0].Bounds,"print shares placements");using(var bitmap=new Bitmap(1000,1500))using(var g=Graphics.FromImage(bitmap)){Check(doc.RenderPage(g,0)==1&&doc.RenderPage(g,1)==2,"print counts per page");}doc.OffsetX=-1.5;doc.OffsetY=2;var b=doc.LabelBounds(0);Check(b.Width==s.Width&&b.Height==s.Height&&Math.Abs(b.X-132.5)<.001,"calibration translates without scale");}
  var multi=new List<BatchRecord>{new BatchRecord{Label=s,Count=1},new BatchRecord{Label=ProjectXml.Clone(s),Count=2}};multi[1].Label.Texts[0].Text="Second";plan=OutputPlan.Create(multi,s);Check(plan.Placements[1].Label.Texts[0].Text=="Second","mixed products sheet");
  foreach(string type in new[]{"QR","Data Matrix"}){var label=LabelSettings.Default();label.HideBarcode=true;label.Texts.Clear();label.Symbols.Add(new SymbolItem{X=5,Y=5,Width=30,Height=30,Matrix=new MatrixContent{Type=type,Data="Žltý čaj 000123"}});using(var scene=VectorArt.Build(label))using(var bitmap=JobOutput.Raster(scene,300)){var reader=new ZXing.BarcodeReader{AutoRotate=true};var decoded=reader.Decode(bitmap);Check(decoded!=null&&decoded.Text=="Žltý čaj 000123",type+" rendered roundtrip");bitmap.Save(Path.Combine(dir,type.Replace(" ","")+".png"));}}
  string imageFile=Path.Combine(dir,"logo.png");using(var bitmap=new Bitmap(40,20))using(var g=Graphics.FromImage(bitmap)){g.Clear(Color.Transparent);g.FillRectangle(Brushes.Red,0,0,20,20);bitmap.Save(imageFile,ImageFormat.Png);}var content=Assets.Import(imageFile);s=LabelSettings.Default();s.Symbols.Add(new SymbolItem{X=2,Y=20,Width=20,Height=10,Rotation=45,Image=content});File.Delete(imageFile);s=ProjectXml.Clone(s);using(var scene=VectorArt.Build(s)){Check(scene.Shapes.Exists(sh=>sh.Bitmap!=null),"image embedded independent of original");string svg=SceneOutput.Svg(scene,new RectangleF(0,0,60,45));Check(svg.Contains("data:image/png;base64,")&&svg.Contains("rotate(45"),"SVG embedded rotated raster");}
  using(var svg=SafeSvg.Read("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 20 20'><path fill='#ff0000' d='M0 0 L20 0 L10 20 Z'/></svg>"))Check(svg.Shapes.Count==1&&svg.Shapes[0].Fill.R==255,"SVG vector geometry color");Reject(()=>SafeSvg.Read("<!DOCTYPE svg [<!ENTITY x SYSTEM 'file:///secret'>]><svg>&x;</svg>"),"SVG DTD rejected");Reject(()=>SafeSvg.Read("<svg><image href='https://example.com/image.png'/></svg>"),"SVG external resource rejected");
  plan=OutputPlan.Create(s);using(var scene=plan.Scene(0))using(var bitmap=JobOutput.Raster(scene,300))bitmap.Save(Path.Combine(dir,"reference.png"));foreach(string format in new[]{"pdf","docx","svg","zpl"}){string file=Path.Combine(dir,"output."+format);JobOutput.Export(file,format,plan,203);Check(new FileInfo(file).Length>100,format+" export");}using(var zip=ZipFile.OpenRead(Path.Combine(dir,"output.docx"))){int svg=0,png=0;foreach(var entry in zip.Entries){if(entry.FullName.EndsWith(".svg"))svg++;if(entry.FullName.EndsWith(".png"))png++;}Check(svg>=3&&svg==png,"Word separate SVG elements and matching fallbacks");}
  using(var form=new MainForm(Path.Combine(dir,"ui.xml"))){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();var preview=Field<PreviewPanel>(form,"preview");Call(form,"AddText");Check(Field<EditHistory>(form,"history").CanUndo,"UI add history");int n=Field<DataGridView>(form,"grid").Rows.Count;Call(form,"StepHistory",false);Check(Field<DataGridView>(form,"grid").Rows.Count==n-1,"UI undo");Call(form,"StepHistory",true);Check(Field<DataGridView>(form,"grid").Rows.Count==n,"UI redo");preview.SelectMany(new[]{0,1},true);Call(form,"Arrange","group");Check(preview.Selection.Count==2,"group retains selection");Call(form,"Arrange","lock");Check(Elements.Locked((LabelSettings)Call(form,"Read"),0),"lock persisted");Call(form,"Arrange","unlock");Call(form,"Apply",LabelSettings.Default());form.Close();}
  File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS "+count+" checks; physical printing not performed.");
 }catch(Exception ex){File.WriteAllText(Path.Combine(dir,"failed.txt"),ex.ToString());Environment.ExitCode=1;}}
}
